#include <iostream>
#include <iomanip>
#include <array>

struct Simpletron {
    static constexpr int MEM_SIZE = 100;
    std::array<int, MEM_SIZE> memory{};
    int accumulator{0};
    int instructionCounter{0};
    int instructionRegister{0};
    int operationCode{0};
    int operand{0};

    void dump() const {
        std::cout << "REGISTERS:\n";
        std::cout << "accumulator:          " << std::showpos << std::internal << std::setfill('0') << std::setw(5) << accumulator << "\n";
        std::cout << std::noshowpos << std::right << std::setfill(' ');
        std::cout << "instructionCounter:   " << std::setfill('0') << std::setw(2) << instructionCounter << "\n";
        std::cout << "instructionRegister:  " << std::showpos << std::internal << std::setfill('0') << std::setw(5) << instructionRegister << "\n";
        std::cout << std::noshowpos << std::right << std::setfill(' ');
        std::cout << "operationCode:        " << std::setfill('0') << std::setw(2) << operationCode << "\n";
        std::cout << "operand:              " << std::setfill('0') << std::setw(2) << operand << "\n";
    }

    void load() {
        int val = 0;
        int index = 0;
        while (index < MEM_SIZE && (std::cin >> val)) {
            if (val == -99999) break;
            if (val >= -9999 && val <= 9999) {
                memory[index++] = val;
            }
        }
    }

    void execute() {
        bool running = true;
        while (running && instructionCounter >= 0 && instructionCounter < MEM_SIZE) {
            instructionRegister = memory[instructionCounter];
            operationCode = instructionRegister / 100;
            operand = instructionRegister % 100;
            bool branched = false;

            switch (operationCode) {
                case 10: // READ
                    std::cin >> memory[operand];
                    break;
                case 11: // WRITE
                    std::cout << "OUTPUT: " << memory[operand] << "\n";
                    break;
                case 20: // LOAD
                    accumulator = memory[operand];
                    break;
                case 21: // STORE
                    memory[operand] = accumulator;
                    break;
                case 30: // ADD
                    accumulator += memory[operand];
                    if (accumulator > 9999 || accumulator < -9999) {
                        std::cout << "*** Accumulator overflow ***\n";
                        dump();
                        return;
                    }
                    break;
                case 32: // DIVIDE
                    if (memory[operand] == 0) {
                        std::cout << "*** Attempt to divide by zero ***\n";
                        std::cout << "*** Simpletron execution abnormally terminated ***\n";
                        dump();
                        return;
                    }
                    accumulator /= memory[operand];
                    break;
                case 40: // BRANCH
                    instructionCounter = operand;
                    branched = true;
                    break;
                case 42: // BRANCHZERO
                    if (accumulator == 0) {
                        instructionCounter = operand;
                        branched = true;
                    }
                    break;
                case 43: // HALT
                    std::cout << "*** Simpletron execution terminated ***\n";
                    running = false;
                    break;
                default:
                    std::cout << "*** Invalid operation code ***\n";
                    dump();
                    return;
            }

            if (!branched && running) {
                ++instructionCounter;
            }
        }
    }
};

int main() {
    Simpletron vm;
    vm.load();
    vm.execute();
    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>

constexpr double PI = 3.141592653589793;

void calcCircumference(double r) {
    std::cout << "Circumference (r=" << std::fixed << std::setprecision(2) << r
              << "): " << 2.0 * PI * r << "\n";
}

void calcArea(double r) {
    std::cout << "Circle Area   (r=" << std::fixed << std::setprecision(2) << r
              << "): " << PI * r * r << "\n";
}

void calcVolume(double r) {
    std::cout << "Sphere Volume (r=" << std::fixed << std::setprecision(2) << r
              << "): " << (4.0 / 3.0) * PI * r * r * r << "\n";
}

int main() {
    using Action = void (*)(double);
    const std::array<Action, 3> menu = {
        calcCircumference,
        calcArea,
        calcVolume
    };

    int choice = 0;
    double radius = 0.0;
    if (std::cin >> choice >> radius) {
        if (choice >= 0 && choice < static_cast<int>(menu.size())) {
            menu[choice](radius);
        } else {
            std::cout << "Invalid menu choice\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

void inspectString(std::string_view sv) {
    std::cout << "String: \"" << sv << "\" | Length: " << sv.length() << "\n";
    std::cout << "Characters: ";
    for (size_t i = 0; i < sv.length(); ++i) {
        std::cout << sv[i] << (i + 1 < sv.length() ? '-' : '\n');
    }
}

int main() {
    std::string token;
    if (std::cin >> token) {
        inspectString(token);
    }
    return 0;
}
